vertexShader:
attribute vec3 aPos; attribute vec4 aData; varying vec2 vUv; varying float vA, vSeed, vLit;
#include <fog_pars_vertex>
void main() {
  vUv = position.xy; vSeed = aData.z; vLit = aData.w;
  vec4 c = viewMatrix * vec4(aPos, 1.); float d = -c.z, r = aData.y, s = sin(aData.x), co = cos(aData.x);
  vec2 corner = vec2(co * position.x - s * position.y, s * position.x + co * position.y) * aData.y;
  vec4 mvPosition = c + vec4(corner, 0., 0.);
  vA = smoothstep(r * .15, r * .9, d) * (1. - smoothstep(2600., 3400., d));
  gl_Position = projectionMatrix * mvPosition;
  #include <fog_vertex>
}

fragmentShader:
uniform float uTime; uniform vec3 uLow, uHigh; varying vec2 vUv; varying float vA, vSeed, vLit;
#include <fog_pars_fragment>
float h(vec2 p) { return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }
float n(vec2 p) { vec2 i = floor(p), f = fract(p); f = f * f * (3. - 2. * f); return mix(mix(h(i), h(i + vec2(1., 0.)), f.x), mix(h(i + vec2(0., 1.)), h(i + vec2(1., 1.)), f.x), f.y); }
void main() {
  vec2 p = vUv * 2.; float r = length(p);
  float f = .55 * n(p * 2.1 + vSeed * 13.) + .3 * n(p * 4.7 - vSeed * 7. + uTime * .02) + .15 * n(p * 9.3 + vSeed);
  float a = smoothstep(1., .25, r + (f - .5) * .9) * vA;
  if (a < .004) discard;
  float lit = clamp(.5 - vUv.y * .9 + (f - .5) * .6, 0., 1.);                                        // the bottom of each puff catches the magma glow
  vec3 col = mix(uHigh, uLow, lit * vLit) * (.75 + .5 * f);
  gl_FragColor = vec4(col, a * .62);
  #include <fog_fragment>
}
